insert into assessment_categories (key, label, icon, "order") values ('cognitive', 'Cognitive', 'brain', 1)
insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('intelligence-profile', 'EvalOtter Intelligence Profile', 'The flagship assessment. Combines logical reasoning, numerical intelligence, memory, verbal reasoning, spatial intelligence, and pattern recognition into one EvalOtter Score.', 'The EvalOtter Intelligence Profile is the flagship assessment — a broad first read across six cognitive domains: logical reasoning, numerical intelligence, memory, verbal reasoning, spatial intelligence, and pattern recognition. It draws a curated subset of questions from the platform''s shared question library (the same items used in the dedicated single-domain assessments), so results are directly comparable to your scores on those assessments. EvalOtter assessments are designed for education, entertainment and self-discovery and are not a substitute for professional psychological, medical or clinical assessment.', 'brain', (select id from assessment_categories where key = 'cognitive'), ('hybrid')::assessment_engine_type, ('medium')::assessment_difficulty, 25, 15, true, ('free')::assessment_access, ('published')::assessment_status)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'logical', 'Logical', 'Pattern detection and deductive inference.', true, 'logical', 1)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'numerical', 'Numerical', 'Arithmetic, percentages, ratios, and sequences.', true, 'logical', 2)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'memory', 'Memory', 'Word and sequence recall.', true, 'memory', 3)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'verbal', 'Verbal', 'Vocabulary and word precision.', true, 'verbal', 4)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'spatial', 'Spatial', 'Visual matrix pattern completion.', true, 'spatial', 5)
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'overall', 0, 30, 'Developing', 'Your broad cognitive profile is still forming across the domains tested. This first read is a starting point, not a verdict — the dedicated single-domain assessments will show you exactly where to focus.', ARRAY['Take the dedicated assessment for your lowest-scoring domain to get a fuller picture.', 'Revisit this profile after practicing in your weaker areas.', 'Use the Brain Profile radar to see your shape at a glance, not just one number.']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'overall', 31, 50, 'Average', 'You show typical performance across most cognitive domains tested, with some unevenness between your strongest and weakest areas.', ARRAY['Check your Brain Profile to see which domain is pulling the average down.', 'Take the single-domain assessments for a more precise read on each area.', 'Revisit this profile periodically to track how your shape changes over time.']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'overall', 51, 70, 'Strong', 'You perform solidly across logical, numerical, memory, verbal, and spatial reasoning, with a reasonably balanced profile.', ARRAY['Take the dedicated assessments to sharpen your understanding of each individual domain.', 'Look at your Brain Profile radar for your single strongest area and lean into it.', 'Retake periodically — this composite is a good way to track overall change over time.']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'overall', 71, 85, 'Very Strong', 'You perform well above average across the cognitive domains tested, with a well-rounded profile and no clear weak spot.', ARRAY['Take the single-domain assessments to find your single sharpest edge.', 'Explore Emotional Intelligence and Creative Assessment to round out your full Brain Profile.', 'Consider what real-world contexts would let you apply this range of ability.']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'intelligence-profile'), 'overall', 86, 100, 'Exceptional', 'You perform exceptionally across logical, numerical, memory, verbal, and spatial reasoning — a rare, well-rounded profile in the top tier of this assessment.', ARRAY['Explore the full catalogue — Emotional Intelligence and Creative Assessment measure dimensions this profile doesn''t touch.', 'Take the single-domain assessments to see just how deep each individual strength runs.', 'Revisit periodically' || chr(59) || ' a broad composite like this is a good long-term benchmark.']::text[], NULL, 5);
